public class Main {
    private static List<String> inputLines = new ArrayList<>();
    private static int index = 0;
    private static int max = 0;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line;
        while ((line = br.readLine()) != null) {
            inputLines.add(line);
        }
        max = inputLines.size();
        System.err.println("\n↑入力 ↓出力");
        solve();
    }

    private static boolean hasNext() {
        return index < max;
    }

    private static String next() {
        if (hasNext()) {
            return inputLines.get(index++);
        } else {
            throw new ArrayIndexOutOfBoundsException("There is no more input");
        }
    }

    private static int nextInt() {
        return myconv(next(), 1);
    }

    private static String[] nextStrArray() {
        return myconv(next(), 2);
    }

    private static int[] nextIntArray() {
        return myconv(next(), 4);
    }

    private static char[] nextCharArray() {
        return myconv(next(), 6);
    }

    private static void myout(String s) {
        System.out.println(s);
    }

    private static int myconv(String i, int no) {
        try {
            switch (no) {
                case 1:
                    return Integer.parseInt(i);
                case 2:
                    return Integer.parseInt(i.split(" ")[0]);
                case 4:
                    return Integer.parseInt(i.split(" ")[0]);
                case 6:
                    return i.charAt(0);
                case 7:
                    return Integer.parseInt(String.valueOf(i.charAt(0)));
                case 8:
                    return Integer.parseInt(i);
                case 9:
                    return Integer.parseInt(i);
                case 0:
                    return Integer.parseInt(i);
                default:
                    return Integer.parseInt(i);
            }
        } catch (Exception e) {
            return 0;
        }
    }

    private static int[] myconvIntArray(String i, int no) {
        try {
            switch (no) {
                case 4:
                    String[] parts = i.split(" ");
                    int[] result = new int[parts.length];
                    for (int j = 0; j < parts.length; j++) {
                        result[j] = Integer.parseInt(parts[j]);
                    }
                    return result;
                default:
                    return new int[]{Integer.parseInt(i)};
            }
        } catch (Exception e) {
            return new int[]{0};
        }
    }

    private static void solve() {
        int[] one = myconvIntArray(next(), 4);
        int L = one[0];
        int R = one[1];
        int C = one[2];

        if (Math.abs(L - R) >= C) {
            int minLR = Math.min(L, R);
